import type { DatabaseSync } from 'node:sqlite';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** Attempts allowed in total, including the first one. */
export const MAX_ATTEMPTS = 3;
/** Simulated duration of one processing step. */
export const STEP_MS = 100;
/** Delay before a failed attempt is retried (within the 250 ms – 2 s window). */
export const RETRY_DELAY_MS = 500;
export const TRANSIENT_ERROR = 'transient failure';

/** A row of the `jobs` table, as SQLite returns it. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  result_output: string | null;
  error: string | null;
  next_run_at: number;
  created_at: string;
  updated_at: string;
}

/** The job JSON shape returned by every endpoint. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.result_output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export function getJobRow(db: DatabaseSync, id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
}

export function listJobRows(db: DatabaseSync): JobRow[] {
  return db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
}

