export interface FieldError {
  field: string;
  message: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

export type Parsed<T> = { ok: true; value: T } | { ok: false; fields: FieldError[] };

const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const MAX_INPUT_LENGTH = 1000;

const isObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

/** Checks the Content-Type header: the media type must be application/json. */
export function checkContentType(contentType: string | undefined): FieldError[] {
  const mediaType = contentType?.split(';')[0]?.trim().toLowerCase();
  if (mediaType === 'application/json') return [];
  return [{ field: 'body', message: 'Content-Type must be application/json' }];
}

/** Validates the Idempotency-Key header, if one was sent. */
export function checkIdempotencyKey(key: string | undefined): FieldError[] {
  if (key === undefined || IDEMPOTENCY_KEY_RE.test(key)) return [];
  return [{ field: 'Idempotency-Key', message: 'must be 1 to 128 characters of A-Z, a-z, 0-9, "_" or "-"' }];
}

/** Parses the raw body text as a JSON object. */
export function parseBody(raw: string): Parsed<Record<string, unknown>> {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return { ok: false, fields: [{ field: 'body', message: 'body must be valid JSON' }] };
  }
  if (!isObject(parsed)) return { ok: false, fields: [{ field: 'body', message: 'body must be a JSON object' }] };
  return { ok: true, value: parsed };
}

function integerIn(v: unknown, min: number, max: number): boolean {
  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
}

/** Validates a job submission body and applies the defaults. */
export function validateNewJob(body: Record<string, unknown>): Parsed<NewJob> {
  const fields: FieldError[] = [];
  const allowed = new Set(['input', 'steps', 'failAttempts']);
  for (const key of Object.keys(body)) {
    if (!allowed.has(key)) fields.push({ field: key, message: 'is not a known field' });
  }

  const { input, steps = 5, failAttempts = 0 } = body;

  if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'is required and must be a string' });
  } else if (input.length < 1 || input.length > MAX_INPUT_LENGTH || input.trim() === '') {
    fields.push({ field: 'input', message: `must be 1 to ${MAX_INPUT_LENGTH} characters and not only whitespace` });
  }

  if (!integerIn(steps, 1, 20)) fields.push({ field: 'steps', message: 'must be an integer from 1 to 20' });
  if (!integerIn(failAttempts, 0, 5)) fields.push({ field: 'failAttempts', message: 'must be an integer from 0 to 5' });

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input: input as string, steps: steps as number, failAttempts: failAttempts as number } };
}

