import type { DatabaseSync } from 'node:sqlite';
import { openDatabase } from './db.ts';
import { MAX_ATTEMPTS, RETRY_DELAY_MS, STEP_MS, TRANSIENT_ERROR, type JobRow } from './jobs.ts';

const HEARTBEAT_MS = 1_000;
const IDLE_POLL_MS = 200;

let stopping = false;

/**
 * Claims the oldest queued job that is due. The select and the update run in one IMMEDIATE
 * transaction, so two workers can never claim the same job.
 */
function claimNext(db: DatabaseSync): JobRow | undefined {
  const now = Date.now();
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db
      .prepare(`SELECT * FROM jobs WHERE status = 'queued' AND next_run_at <= ? ORDER BY seq LIMIT 1`)
      .get(now) as unknown as JobRow | undefined;
    if (!row) {
      db.exec('COMMIT');
      return undefined;
    }
    db.prepare(`UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ? WHERE seq = ?`).run(
      new Date(now).toISOString(),
      row.seq,
    );
    db.exec('COMMIT');
    return { ...row, status: 'running', attempts: row.attempts + 1, completed: 0 };
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

/**
 * Puts jobs that were `running` back in the queue. This happens after a crash (the job was
 * interrupted mid-attempt) and on graceful shutdown. The interrupted attempt still counts. If it
 * was the last allowed attempt, the rerun takes its place, so no attempt number is exceeded.
 */
function requeueInterrupted(db: DatabaseSync): number {
  const result = db
    .prepare(
      `UPDATE jobs
         SET status = 'queued',
             attempts = CASE WHEN attempts >= ? THEN ? ELSE attempts END,
             completed = 0,
             next_run_at = 0,
             updated_at = ?
       WHERE status = 'running'`,
    )
    .run(MAX_ATTEMPTS, MAX_ATTEMPTS - 1, new Date().toISOString());
  return Number(result.changes);
}

function writeHeartbeat(db: DatabaseSync): void {
  db.prepare(
    'INSERT INTO worker_heartbeat (id, seen_at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET seen_at = excluded.seen_at',
  ).run(Date.now());
}

/** Runs one attempt of a claimed job: fail at the first step if simulated to fail, else run every step. */
async function runAttempt(db: DatabaseSync, job: JobRow): Promise<void> {
  if (job.attempts <= job.fail_attempts) {
    const now = new Date().toISOString();
    if (job.attempts < MAX_ATTEMPTS) {
      db.prepare(
        `UPDATE jobs SET status = 'queued', completed = 0, next_run_at = ?, updated_at = ? WHERE seq = ?`,
      ).run(Date.now() + RETRY_DELAY_MS, now, job.seq);
    } else {
      db.prepare(`UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ? WHERE seq = ?`).run(
        TRANSIENT_ERROR,
        now,
        job.seq,
      );
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return; // left as `running`; requeued by the shutdown path
    db.prepare('UPDATE jobs SET completed = ?, updated_at = ? WHERE seq = ?').run(step, new Date().toISOString(), job.seq);
  }

  db.prepare(
    `UPDATE jobs SET status = 'completed', completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE seq = ?`,
  ).run(job.input.toUpperCase(), new Date().toISOString(), job.seq);
}

