import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import type { DatabaseSync } from 'node:sqlite';
import { openDatabase } from './db.ts';
import { getJobRow, listJobRows, toJob, type Job } from './jobs.ts';
import { checkContentType, checkIdempotencyKey, parseBody, validateNewJob, type FieldError, type NewJob } from './validation.ts';

const MAX_BODY_BYTES = 64 * 1024;
/** A worker heartbeat older than this means the worker is down. */
const WORKER_UP_WINDOW_MS = 3_000;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function invalid(res: ServerResponse, fields: FieldError[]): void {
  sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

/**
 * Creates the job in one IMMEDIATE transaction, or, when the idempotency key was seen before,
 * returns the job it created (or a conflict if the payload differs). The key and the job are
 * committed together, so a key never yields more than one job, even across restarts.
 */
function findOrCreateJob(job: NewJob, key: string | undefined): { job: Job; created: boolean } | { conflict: true } {
  const now = new Date().toISOString();
  const id = randomUUID();
  const payload = JSON.stringify({ input: job.input, steps: job.steps, failAttempts: job.failAttempts });

  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== undefined) {
      const existing = db.prepare('SELECT payload, job_id FROM idempotency WHERE key = ?').get(key) as
        | { payload: string; job_id: string }
        | undefined;
      if (existing) {
        db.exec('COMMIT');
        if (existing.payload !== payload) return { conflict: true };
        const row = getJobRow(db, existing.job_id);
        if (!row) throw new Error(`idempotency key ${key} points at missing job ${existing.job_id}`);
        return { job: toJob(row), created: false };
      }
    }
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, next_run_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, 0, ?, ?)`,
    ).run(id, job.input, job.steps, job.failAttempts, now, now);
    if (key !== undefined) {
      db.prepare('INSERT INTO idempotency (key, payload, job_id) VALUES (?, ?, ?)').run(key, payload, id);
    }
    db.exec('COMMIT');
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
  return { job: toJob(getJobRow(db, id)!), created: true };
}

async function handleCreateJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const keyHeader = req.headers['idempotency-key'];
  const key = keyHeader === undefined ? undefined : String(keyHeader);

  const fields: FieldError[] = [...checkContentType(req.headers['content-type']), ...checkIdempotencyKey(key)];
  let job: NewJob | undefined;
  if (tooLarge) {
    fields.push({ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` });
  } else if (!fields.some((f) => f.field === 'body')) {
    const parsed = parseBody(text);
    if (parsed.ok) {
      const validated = validateNewJob(parsed.value);
      if (validated.ok) job = validated.value;
      else fields.push(...validated.fields);
    } else {
      fields.push(...parsed.fields);
    }
  }

  if (fields.length > 0 || job === undefined) return invalid(res, fields);

  const result = findOrCreateJob(job, key);
  if ('conflict' in result) {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, result.created ? 201 : 200, result.job);
}

function handleListJobs(res: ServerResponse): void {
  send(res, 200, { jobs: listJobRows(db).map(toJob) });
}

function handleGetJob(res: ServerResponse, id: string): void {
  const row = getJobRow(db, id);
  if (!row) return sendError(res, 404, 'not_found', 'No job with that id.');
  send(res, 200, toJob(row));
}

function handleHealth(res: ServerResponse): void {
  const hb = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id = 1').get() as { seen_at: number } | undefined;
  const up = hb !== undefined && Date.now() - hb.seen_at <= WORKER_UP_WINDOW_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function methodNotAllowed(res: ServerResponse, allow: string[]): void {
  sendError(res, 405, 'method_not_allowed', `Method not allowed. Use ${allow.join(', ')}.`);
  res.setHeader('allow', allow.join(', '));
}

function decodeId(raw: string): string | undefined {
  try {
    return decodeURIComponent(raw);
  } catch {
    return undefined;
  }
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method === 'HEAD' ? 'GET' : req.method;

  if (pathname === '/health') return method === 'GET' ? handleHealth(res) : methodNotAllowed(res, ['GET']);

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(method === 'HEAD' ? undefined : uiHtml);
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return handleListJobs(res);
    if (method === 'POST') return handleCreateJob(req, res);
    return methodNotAllowed(res, ['GET', 'POST']);
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    const id = decodeId(match[1]!);
    if (id === undefined) return sendError(res, 404, 'not_found', 'No job with that id.');
    if (method === 'GET') return handleGetJob(res, id);
    return methodNotAllowed(res, ['GET']);
  }

  sendError(res, 404, 'not_found', 'No such route.');
}

const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

let closing = false;
function shutdown(): void {
  if (closing) return;
  closing = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), 1_000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

const port = Number(process.env.PORT || 3000);
server.on('error', (e) => {
  console.error(`server error: ${e.message}`);
  process.exit(1);
});
server.listen(port, () => console.log(`server listening on ${port}`));

