  } else if (!fields.some((f) => f.field === 'body')) {
    const parsed = parseBody(text);
    if (parsed.ok) {
      const validated = validateNewJob(parsed.value);
      if (validated.ok) job = validated.value;
      else fields.push(...validated.fields);
    } else {
      fields.push(...parsed.fields);
    }
  }

  if (fields.length > 0 || job === undefined) return invalid(res, fields);

  const result = findOrCreateJob(job, key);
  if ('conflict' in result) {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, result.created ? 201 : 200, result.job);
}

function handleListJobs(res: ServerResponse): void {
  send(res, 200, { jobs: listJobRows(db).map(toJob) });
}

function handleGetJob(res: ServerResponse, id: string): void {
  const row = getJobRow(db, id);
  if (!row) return sendError(res, 404, 'not_found', 'No job with that id.');
  send(res, 200, toJob(row));
}

function handleHealth(res: ServerResponse): void {
  const hb = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id = 1').get() as { seen_at: number } | undefined;
  const up = hb !== undefined && Date.now() - hb.seen_at <= WORKER_UP_WINDOW_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function methodNotAllowed(res: ServerResponse, allow: string[]): void {
  sendError(res, 405, 'method_not_allowed', `Method not allowed. Use ${allow.join(', ')}.`);
  res.setHeader('allow', allow.join(', '));
}

function decodeId(raw: string): string | undefined {
  try {
    return decodeURIComponent(raw);
  } catch {
    return undefined;
  }
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method === 'HEAD' ? 'GET' : req.method;

  if (pathname === '/health') return method === 'GET' ? handleHealth(res) : methodNotAllowed(res, ['GET']);

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(req.method === 'HEAD' ? undefined : uiHtml);
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return handleListJobs(res);
    if (method === 'POST') return handleCreateJob(req, res);
    return methodNotAllowed(res, ['GET', 'POST']);
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    const id = decodeId(match[1]!);
    if (id === undefined) return sendError(res, 404, 'not_found', 'No job with that id.');
    if (method === 'GET') return handleGetJob(res, id);
    return methodNotAllowed(res, ['GET']);
  }

  sendError(res, 404, 'not_found', 'No such route.');
}

const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

let closing = false;
function shutdown(): void {
  if (closing) return;
  closing = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), 1_000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

const port = Number(process.env.PORT || 3000);
server.on('error', (e) => {
  console.error(`server error: ${e.message}`);
  process.exit(1);
});
server.listen(port, () => console.log(`server listening on ${port}`));
